# Creates the 7 iOS UX issues in faheeds/lunchpad-ios for the agent pipeline.
#
# These can be created now; they sit unlabeled until the iOS pipeline is
# live. The pipeline goes live ONLY after you (a) merge the
# chore/agent-pipeline PR and (b) add the ANTHROPIC_API_KEY + AGENT_PAT
# secrets to the repo.
#
# This script does NOT label anything - the iOS pipeline is brand new,
# so you should kick the first issue deliberately once it is confirmed
# working. Label one issue at a time (the concurrency group cancels
# queued runs otherwise).
#
# Run from anywhere.

$ErrorActionPreference = "Stop"
$repo = "faheeds/lunchpad-ios"

function New-Issue($title, $b64) {
  $f = Join-Path $env:TEMP ("iosux-" + [Guid]::NewGuid().ToString() + ".md")
  [IO.File]::WriteAllBytes($f, [Convert]::FromBase64String($b64))
  $url = gh issue create --repo $repo --title $title --body-file $f
  Remove-Item $f -ErrorAction SilentlyContinue
  Write-Host "created: $url" -ForegroundColor Green
  return ($url -split '/')[-1]
}

$n1 = New-Issue "Editorial light theme: theme system + auth & home screens" ""
$n2 = New-Issue "Editorial light theme: ordering screens (menu, order, cart)" ""
$n3 = New-Issue "Editorial light theme: account, weekly, success screens" ""
$n4 = New-Issue "Fix: cart cleared before payment is confirmed (data loss)" ""
$n5 = New-Issue "Fix: menu-modal dead-end + add-child attaches to wrong school" ""
$n6 = New-Issue "iOS order history: detail view + modify/cancel parity with web" ""
$n7 = New-Issue "iOS native polish + consistency pass" ""

Write-Host ""
Write-Host "7 iOS issues created (all unlabeled)." -ForegroundColor Green
Write-Host "Once the pipeline PR is merged and both secrets are set, label them" -ForegroundColor Yellow
Write-Host "ONE AT A TIME, waiting for each run to start before labeling the next:" -ForegroundColor Yellow
Write-Host "  gh issue edit $n1 --repo $repo --add-label agent-ready" -ForegroundColor Yellow
Write-Host "Recommended order: $n1 (theme system) -> $n2 -> $n3 (restyle) -> $n4 (cart data loss)" -ForegroundColor Yellow
Write-Host "  -> $n5 (two bugs) -> $n6 (history parity) -> $n7 (polish)." -ForegroundColor Yellow
Write-Host "Tip: run $n4 (cart data-loss fix) early - it is a real bug, not just polish." -ForegroundColor Yellow
